 const options=fixture(t,'components',Array.from({length:14},(_,n)=>`pub fn item_${n}()->u8{${n}u8}`).join('\n')),plain=legacy.planRegeneration(options);legacy.applyRegenerationPlan(plain);const metaPath=plain.manifest.projects[0].targets.meta,original=fs.readFileSync(join(options.root,metaPath),'utf8'),meta=JSON.parse(original),rootOnly={...meta};delete rootOnly.checkedSemanticProgram;delete rootOnly.targetSemanticProgram;delete rootOnly.concreteSyntaxMeta;
